CREATE TABLE IF NOT EXISTS institutions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, classroom VARCHAR(255), school VARCHAR(255));
CREATE TABLE IF NOT EXISTS letter_sign_pairs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image_id INTEGER, letter VARCHAR(255));
CREATE TABLE IF NOT EXISTS roles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, authority VARCHAR(255));
CREATE TABLE IF NOT EXISTS sections (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, icon_id INTEGER, image_id INTEGER, name VARCHAR(255));
CREATE TABLE IF NOT EXISTS categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image_id INTEGER, is_expanded BOOLEAN NOT NULL DEFAULT FALSE, is_favorite BOOLEAN NOT NULL DEFAULT FALSE, name VARCHAR(255), parent_id BIGINT REFERENCES categories(id), section_id BIGINT REFERENCES sections(id));
CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, address VARCHAR(255), birthday DATE, email VARCHAR(255), mobile VARCHAR(255), name VARCHAR(255), password VARCHAR(255), institution_id BIGINT REFERENCES institutions(id), role_id BIGINT REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS feedbacks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, description VARCHAR(255), sent_at TIMESTAMP(6), type VARCHAR(255), user_id BIGINT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, is_read BOOLEAN NOT NULL DEFAULT FALSE, message VARCHAR(255), sent_at TIMESTAMP(6), receiver_id BIGINT REFERENCES users(id), sender_id BIGINT REFERENCES users(id));
